import {renderHome, mountHome, renderGallery, mountGallery} from './scenes.js';

const plants = [
  {id:'rose',name:'月季',latin:'Rosa chinensis',no:'NB—001',value:'08',bg:'#ec9aaa',ink:'#622f35',art:'rose.webp',source:'农科村庭院修剪枝',intro:'把一枝花留给下一座阳台。月季适合愿意观察新芽、耐心等待花期的人。',light:'充足日照 · 每日约 4–6 小时',level:'需要一点耐心',status:'演示可预约',tip:'取约 12–15 厘米健壮枝，保留上方两片叶，斜剪基部后插入疏松介质。保持明亮、通风与微湿。',care:'初期避开正午暴晒；新芽出现不一定代表已经生根。'},
  {id:'crape',name:'紫薇',latin:'Lagerstroemia indica',no:'NB—002',value:'12',bg:'#b889c9',ink:'#4f365a',art:'crape.webp',source:'农科村道路绿化修剪枝',intro:'夏天的细小褶皱花，像一封开得很慢的信。枝条适合光照充足的空间。',light:'充足日照 · 每日约 5 小时以上',level:'入门友好',status:'演示可预约',tip:'选半木质化枝段，剪去下部叶片，插入透气介质约枝长的三分之一。避免积水。',care:'保持明亮和通风。生根前介质微湿即可，忌长期浸水。'},
  {id:'osmanthus',name:'桂花',latin:'Osmanthus fragrans',no:'NB—003',value:'16',bg:'#f2cf66',ink:'#4e532d',art:'osmanthus.webp',source:'农科村园圃整形枝',intro:'细碎的香气会先于花被发现。桂花需要耐心与稳定的湿度。',light:'明亮散射光 · 可接受半日照',level:'需要一点耐心',status:'演示可预约',tip:'使用当年生健壮枝，保留少量叶片，插在疏松湿润的介质中，避免直晒。',care:'湿度稳定比频繁浇水更重要；不要用力拔出检查根系。'},
  {id:'hydrangea',name:'绣球',latin:'Hydrangea macrophylla',no:'NB—004',value:'20',bg:'#76b7de',ink:'#344d73',art:'hydrangea.webp',source:'农科村花园季节修剪枝',intro:'一团蓝紫色，留住湿润季节的形状。适合明亮但不过晒的位置。',light:'明亮散射光 · 避开烈日',level:'入门友好',status:'演示可预约',tip:'选无花的嫩枝，保留顶部半片叶，插入湿润透气的介质，并维持空气湿度。',care:'叶片容易失水，初期可适当遮阴；注意通风，别把容器完全密封。'},
  {id:'jasmine',name:'茉莉',latin:'Jasminum sambac',no:'NB—005',value:'06',bg:'#6fc89e',ink:'#245640',art:'jasmine.webp',source:'农科村庭院更新枝',intro:'细白的花像写在叶间的小字。喜欢温暖、明亮又有空气流动的地方。',light:'明亮日照 · 每日约 4 小时',level:'入门友好',status:'演示可预约',tip:'剪取健康新枝，去掉下部叶片，浅插于排水良好的介质，维持轻微湿润。',care:'温暖时更容易生根；冬季避免低温和冷风直吹。'},
  {id:'rosemary',name:'迷迭香',latin:'Salvia rosmarinus',no:'NB—006',value:'10',bg:'#87bbb5',ink:'#315858',art:'rosemary.webp',source:'农科村香草圃修剪枝',intro:'用指尖轻碰叶片，香气就会醒来。它喜欢阳光，也喜欢干爽的根。',light:'充足日照 · 每日约 5 小时',level:'留意排水',status:'演示可预约',tip:'剪取非开花的嫩枝，摘去下部针叶，插入颗粒比例较高的介质。',care:'最常见的问题是水太多；表层稍干再浇，不要让盆底积水。'},
  {id:'gardenia',name:'栀子',latin:'Gardenia jasminoides',no:'NB—007',value:'18',bg:'#bfd786',ink:'#46583f',art:'gardenia.webp',source:'农科村公共花境修剪枝',intro:'一朵白花把夏夜照亮。它偏爱明亮湿润的空气与偏酸性的土。',light:'明亮散射光 · 柔和晨光',level:'需要一点耐心',status:'演示可预约',tip:'使用半木质化枝，保留两片叶，插在疏松偏酸的介质中，保持温暖。',care:'叶黄可先检查积水和光照；避免频繁改变摆放位置。'},
  {id:'bougainvillea',name:'三角梅',latin:'Bougainvillea glabra',no:'NB—008',value:'22',bg:'#ec8a91',ink:'#773b39',art:'bougainvillea.webp',source:'农科村门廊整枝',intro:'纸一样轻的苞片，却有很旺盛的生命力。为阳光明亮的庭院准备。',light:'充足日照 · 每日约 6 小时',level:'留意温度',status:'演示可预约',tip:'选成熟而健康的枝段，去叶后插入排水良好的介质；保持温暖，切勿反复挪动。',care:'怕冷、怕涝；光照不足时枝叶长势会减弱。'}
];
const P = Object.fromEntries(plants.map(x=>[x.id,x]));
const initial = {saved:['rose','osmanthus'],claims:[{id:'DEMO-2026-01',plantId:'crape',nick:'演示访客',place:'阳台',light:'充足日照',form:'已生根幼苗',status:'claimed',date:'2026.08.18',demo:true}],postcards:[{id:'demo-post',plantId:'crape',date:'2026.09.03',status:'抽出新芽',text:'第十七天，枝条顶端有了小小的绿点。先继续耐心等根。',photo:'',demo:true}],letters:[],unread:true};
const load = () => {try {const x=JSON.parse(localStorage.getItem('next-branch-demo'));return x&&Array.isArray(x.claims)?x:structuredClone(initial)}catch{return structuredClone(initial)}};
let data=load(),focusId=null,openLetterId=null,originView='home',claimForm={nick:'',place:'',light:'',form:''},recordForm={status:'抽出新芽',text:'',photo:''},letterForm={plantId:'rose',category:'扦插',title:'',text:'',photo:''};
const app=document.querySelector('#app');
const persist=()=>localStorage.setItem('next-branch-demo',JSON.stringify(data));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stampTeeth=`<svg class="stamp-teeth" viewBox="0 0 220 280" preserveAspectRatio="none" aria-hidden="true"><rect x="10" y="10" width="200" height="260"/>${Array.from({length:21},(_,i)=>`<circle cx="${10+i*10}" cy="10" r="5.4"/><circle cx="${10+i*10}" cy="270" r="5.4"/>`).join('')}${Array.from({length:27},(_,i)=>`<circle cx="10" cy="${10+i*10}" r="5.4"/><circle cx="210" cy="${10+i*10}" r="5.4"/>`).join('')}</svg>`;
function stamp(id,small=false){const p=P[id];return `<div class="stamp ${small?'small':''}" style="--stamp-bg:${p.bg};--stamp-ink:${p.ink}">${stampTeeth}<div class="stamp-inner"><div class="stamp-top"><span>中国 · 成都<br>NONGKE POST</span><b class="stamp-emblem">NB</b></div><img class="stamp-art" src="./assets/${p.art}" alt="${p.name}植物插画" draggable="false"><span class="stamp-vertical">BOTANICAL SERIES · 2026</span><div class="stamp-bottom"><span><span class="stamp-name">${p.name}</span><span class="stamp-latin">${p.latin}</span></span><span class="stamp-index">${p.value}<small> / ${p.no}</small></span></div></div></div>`}
const navLabels=[['home','邮票馆','INDEX'],['claim-list','领取枝条','COLLECT'],['album','我的邮册','ALBUM'],['letters','枝友来信','LETTERS']];
function nav(current){const section=current==='detail'||current==='story'?originView:current==='claim'?'claim-list':current==='growth'?'album':current==='write-letter'?'letters':current;return `<nav class="main-nav" aria-label="主要导航">${navLabels.map(([id,cn,en])=>`<button data-nav="${id}" class="${section===id?'active':''}">${cn}<small>${en}</small></button>`).join('')}</nav>`}
function header(){return ''}
const hashParts=()=>{let [view,id]=location.hash.replace(/^#/,'').split('/');return [view||'home',id]};
function go(view,id){focusId=null;openLetterId=null;const next=`#${view}${id?'/'+id:''}`;if(location.hash===next){render();window.scrollTo(0,0)}else location.hash=next}
function render(){const [view,id]=hashParts();let body=view==='home'?home():view==='detail'?detail(id):view==='claim'?claim(id):view==='claim-list'?claimList():view==='album'?album():view==='growth'?growth(id):view==='story'?story(id):view==='letters'?letters(id):view==='write-letter'?writeLetter():home();app.innerHTML=header()+body+nav(view);document.body.dataset.view=view;bind();if(view==='home')mountHome(plants,(id,el)=>focus(id,el));if(view==='claim-list')mountGallery();}
function home(){return renderHome(plants,stamp)}
function detail(id){const p=P[id]||plants[0];return `<main class="page detail-page"><div class="detail-top"><button class="text-back" data-nav="${originView}">← 返回${originView==="claim-list"?"枝条展馆":originView==="album"?"我的邮册":"邮票馆"}</button><span class="eyebrow">枝条档案 · ${p.no}</span></div><div class="detail-stage"><div class="detail-stamp">${stamp(p.id)}</div></div><article class="fact-sheet"><span class="serial">✳ NONGKE BOTANICAL POST / ${p.no}</span><h1>${p.name}</h1><div class="latin-name">${p.latin}</div><p class="intro">${p.intro}</p><dl class="fact-grid"><div class="fact"><dt>枝条来源</dt><dd>${p.source}</dd></div><div class="fact"><dt>当前领取状态</dt><dd>${p.status}</dd></div><div class="fact"><dt>适宜光照</dt><dd>${p.light}</dd></div><div class="fact"><dt>养护难度</dt><dd>${p.level}</dd></div></dl><div class="detail-process"><h2>扦插小纸条 / ROOTING NOTE</h2><p>${p.tip}</p></div><div class="detail-actions"><button class="solid-action" data-claim="${p.id}">接收这一枝 <span>↗</span></button><button class="line-action" data-story="${p.id}">看看它的故事 <span>→</span></button><button class="line-action" data-care="${p.id}">养护来信 <span>→</span></button><button class="line-action" data-save="${p.id}">${data.saved.includes(p.id)?'从收藏邮票中移除':'收藏这枚邮票'} <span>☆</span></button></div></article></main>`}
function claimList(){return renderGallery(plants,stamp)}
function options(field,values){return `<div class="option-row">${values.map(x=>`<button type="button" class="option ${claimForm[field]===x?'selected':''}" data-option="${field}" data-value="${x}">${x}</button>`).join('')}</div>`}
function fit(){const {place,light,form}=claimForm;const p=P[hashParts()[1]]||plants[0];if(!place||!light||!form)return {type:'neutral',title:'等待填写 / AWAITING DETAILS',text:'选择放置位置、光照与枝条形态后，这里会出现演示适宜度与养护提醒。'};const sun=p.light.includes('充足');const bad=sun&&light==='明亮散射光'&&place==='窗边';return bad?{type:'warn',title:'先为它找一处更亮的位置',text:`${p.name}更偏爱充足日照。若只有柔和窗边光，可以考虑绣球或栀子，也可以重新选择放置位置。`}:{type:'good',title:'这枝或许适合你的新家',text:`${p.care} ${form==='未生根枝条'?'领取时可在驿站体验扦插指导。':'领取后先让幼苗适应新环境。'}`}}
function claim(id){const p=P[id]||plants[0];const current=[...data.claims].reverse().find(x=>x.plantId===p.id&&!x.id.startsWith('DEMO-'));if(current)return ticket(current);const f=fit();return `<main class="page claim-page"><div class="claim-head"><button class="text-back" data-detail="${p.id}">← 回到${p.name}邮票</button><h1>一张寄往新家的<br>枝条邮单。</h1><p>线下自取 · 演示预约流程</p></div><section class="form-paper"><div class="form-top"><div><strong>BRANCH MAIL</strong><span>农科村枝条邮局 / 领取单 001</span></div><div class="postage">NB<br>06</div></div><div class="form-row"><label>寄出地</label><strong>成都农科村 · 枝条再生驿站</strong></div><div class="form-row"><label>植物 / 编号</label><strong>${p.name} &nbsp; ${p.no}</strong></div><div class="form-row"><label for="claim-nick">收件人昵称</label><input id="claim-nick" class="form-input" placeholder="如何称呼你？" maxlength="18" value="${esc(claimForm.nick)}"></div><div class="form-block"><label>01 / 你准备把这一枝放在哪里？</label>${options('place',['阳台','窗边','庭院'])}</div><div class="form-block"><label>02 / 那里的光照如何？</label>${options('light',['充足日照','半日照','明亮散射光'])}</div><div class="form-block"><label>03 / 想领取哪一种形态？</label><small>现场提供情况以驿站实际信息为准</small>${options('form',['未生根枝条','已生根幼苗'])}</div><div class="suitability ${f.type==='warn'?'warn':''}"><strong>${f.title}</strong>${f.text}</div><div class="form-foot"><button class="solid-action" id="submit-claim">生成领取邮单 <span>↗</span></button><span class="micro">这是一段本地演示体验，不代表真实库存或预约成功。</span></div><p class="required-hint" id="claim-error" hidden>请填写昵称并完成全部选择。</p></section></main>`}
function fakeQr(id){let n=0;for(const c of id)n+=c.charCodeAt(0);return `<div class="fake-qr" aria-label="演示二维码区域，不可用于核销">${Array.from({length:121},(_,i)=>`<i class="${(i*7+n+i*i)%11<5?'on':''}"></i>`).join('')}</div>`}
function ticket(c){const p=P[c.plantId];return `<main class="page claim-page"><div class="claim-head"><button class="text-back" data-detail="${p.id}">← 回到${p.name}邮票</button><h1>枝条的下一站，<br>写好了。</h1><p>电子邮单 · 本地演示数据</p></div><section class="form-paper"><div class="form-top"><div><strong>BRANCH MAIL</strong><span>农科村枝条邮局 / 电子邮单</span></div><div class="postage">NB<br>POST</div></div><div class="claim-ticket"><div class="ticket-stamp">${stamp(p.id,true)}</div><div class="eyebrow">TO A NEW HOME / ${esc(c.id)}</div><h2 class="ticket-title">${p.name}<br>正在出发。</h2><p class="ticket-sub">寄给 ${esc(c.nick)} 的一根枝条</p>${c.status==='claimed'?'<div class="red-postmark">已领取<br><small>DEMO PICKUP</small></div>':''}<dl class="ticket-dl"><div><dt>枝条编号</dt><dd>${p.no}</dd></div><div><dt>寄出地</dt><dd>成都农科村</dd></div><div><dt>领取地点</dt><dd>农科村枝条再生驿站</dd></div><div><dt>选择</dt><dd>${esc(c.form)} · ${esc(c.place)}</dd></div><div><dt>当前状态</dt><dd>${c.status==='claimed'?'演示已领取':'演示预约待现场确认'}</dd></div></dl><div class="ticket-bottom">${fakeQr(c.id)}<p>此处为演示二维码区域，不可用于真实核销。请以驿站实际开放与现场指导信息为准。</p></div><div class="ticket-actions">${c.status==='reserved'?`<button class="solid-action" data-pickup="${c.id}">模拟现场领取并盖戳 <span>↗</span></button>`:''}<button class="line-action" data-nav="album">打开我的邮册 <span>→</span></button><button class="line-action" data-detail="${p.id}">返回植物资料 <span>←</span></button></div></div></section></main>`}
function album(){const claimed=data.claims.filter(x=>x.status==='claimed');return `<main class="page album-page"><div class="page-head"><div><span class="eyebrow">A PERSONAL COLLECTION / DEMO</span><h1 class="page-title"><span class="cn">我的邮册</span>ALBUM</h1><p class="page-intro">收藏邮票是一种喜欢；领取枝条，才是另一段生长的开始。</p></div><div class="page-counter">VOL.<br>01</div></div><div class="album-section"><div class="section-heading"><h2>收藏的邮票</h2><span>SAVED / ${String(data.saved.length).padStart(2,'0')}</span></div>${data.saved.length?`<div class="album-stamps">${data.saved.map(id=>`<div class="album-stamp-wrap"><button class="album-stamp" data-detail="${id}" aria-label="查看收藏的${P[id].name}邮票">${stamp(id,true)}</button></div>`).join('')}</div>`:'<p class="empty-note">邮册这一页还空着。到邮票馆挑一枚喜欢的吧。</p>'}</div><div class="album-section"><div class="section-heading"><h2>真正领取的枝条</h2><span>RECEIVED / ${String(claimed.length).padStart(2,'0')}</span></div>${claimed.length?`<div class="branch-list">${claimed.map(c=>`<button class="branch-item" data-growth="${c.plantId}"><img src="./assets/${P[c.plantId].art}" alt=""><span><strong>${P[c.plantId].name}</strong><small>${P[c.plantId].no} · 已领取 ${c.demo?'· 演示记录':''}<br>翻阅生长明信片</small></span><span class="arrow">↗</span></button>`).join('')}</div>`:'<p class="empty-note">还没有领取过枝条。完成邮单后可模拟现场领取，让枝条进入这里。</p>'}</div>${data.unread?`<button class="unread-letter" id="unread-letter"><span class="icon">✉</span><span><strong>有一封未读回信</strong>演示来信 · 紫薇扦插的养护建议</span><span style="margin-left:auto">→</span></button>`:''}<div class="album-section"><div class="section-heading"><h2>说明</h2><span>LOCAL DEMO</span></div><p class="empty-note">本邮册数据保存在当前浏览器。页面中的示例领取、明信片与回信均为演示内容。</p></div></main>`}
function growth(id){if(!data.claims.some(x=>x.plantId===id&&x.status==='claimed'))return story(id);const p=P[id]||plants[0];const records=data.postcards.filter(x=>x.plantId===p.id);return `<main class="page growth-page"><div class="growth-header"><button class="text-back" data-nav="album">← 返回我的邮册</button><h1>${p.name}的生长来信</h1><p>${p.no} · 左右翻阅，轻点明信片看背面 · ${records.length} 张${records.some(x=>x.demo)?' · 含演示记录':''}</p></div>${records.length?`<div class="postcard-track">${records.map((x,i)=>`<div class="postcard" role="button" tabindex="0" aria-label="翻转第${i+1}张${p.name}生长明信片"><div class="postcard-inner"><div class="postcard-face postcard-front"><div class="photo ${x.photo?'':'art-photo'}"><img src="${x.photo||'./assets/'+p.art}" alt="${x.photo?'用户上传的植物照片':'演示植物插画'}"></div><div class="postcard-caption"><strong>${esc(x.status)}</strong><span>${esc(x.date)} ↻ 翻面</span></div></div><div class="postcard-face postcard-back"><div class="back-head"><span>FROM MY BRANCH</span><span>${p.no}</span></div><div class="mini-stamp">${stamp(p.id,true)}</div><h3>${/暂未生根|枯萎/.test(x.status)?"植物标本卡":"寄给以后的自己"}</h3><p>${esc(x.text)}</p>${/暂未生根|枯萎/.test(x.status)?`<p class="specimen-advice">${x.status==="枯萎了"?"妥善清理枯枝和介质，清洗容器；下一次可换一枝重新尝试。":"再给它一点时间，保持通风和微湿；若枝条变软发黑，可重新选择健康枝条。"}</p>`:""}<div class="back-sign">${esc(x.date)} · ${x.demo?'演示明信片':'我的近况'}</div>${/成功生根|暂未生根|枯萎/.test(x.status)?`<div class="memory-mark">${x.status==='成功生根'?'生根纪念':'植物标本'}<br>NB POST</div>`:''}</div></div></div>`).join('')}</div>`:'<p class="empty-note" style="padding:20px 22px">还没有近况。寄出第一张明信片吧。</p>'}<div class="growth-controls"><button class="solid-action" id="show-record-form">寄出一张近况 <span>↗</span></button><button class="line-action" data-detail="${p.id}">植物资料 <span>→</span></button></div><section class="compose-paper" id="record-form" hidden><h2>寄出一张近况</h2><p>每一段生长都值得保存。生根、停滞或枯萎，都可以诚实记下来。</p><label>01 / 植物照片</label><div class="upload-box" id="photo-box"><span>＋ 轻点上传植物照片</span><input id="record-photo" type="file" accept="image/*" aria-label="上传植物照片"></div><label for="record-status">02 / 现在的状态</label><select id="record-status"><option>抽出新芽</option><option>正在生根</option><option>成功生根</option><option>暂未生根</option><option>枯萎了</option></select><label for="record-text">03 / 写一句观察</label><textarea id="record-text" placeholder="今天，它有了什么变化？" maxlength="180"></textarea><button class="solid-action" id="submit-record">生成明信片 <span>↗</span></button><p id="record-error" class="required-hint" hidden>请上传照片并写一句观察。</p></section></main>`}
const publicStories={rose:[['2026.09.02','刚刚安家','带回的月季枝条先住在明亮的窗边，今天给它留了一张影像。'],['2026.09.24','抽出新芽','顶部有了新叶。继续保持通风，再等等根系的消息。']],crape:[['2026.08.18','开始扦插','把紫薇放进疏松的介质，给它留一个温暖的新位置。'],['2026.09.03','抽出新芽','叶芽长大了一点，但还不能太早判断已经生根。']],hydrangea:[['2026.08.20','刚刚安家','把叶片剪去一半，在柔和的光里等待。']]};
function story(id){const p=P[id]||plants[0];const records=publicStories[p.id]||[['2026.09.01','刚刚安家',`这枚${p.name}邮票的演示枝条，开始了一段新的生长记录。`]];return `<main class="page growth-page"><div class="growth-header"><button class="text-back" data-detail="${p.id}">← 返回${p.name}资料</button><h1>${p.name}的故事</h1><p>${p.no} · 公开生长记录演示 · 左右翻阅，轻点明信片看背面</p></div><div class="postcard-track">${records.map((r,i)=>`<div class="postcard" role="button" tabindex="0" aria-label="翻转第${i+1}张${p.name}公开生长明信片"><div class="postcard-inner"><div class="postcard-face postcard-front"><div class="photo art-photo"><img src="./assets/${p.art}" alt="${p.name}演示植物插画"></div><div class="postcard-caption"><strong>${r[1]}</strong><span>${r[0]} ↻ 翻面</span></div></div><div class="postcard-face postcard-back"><div class="back-head"><span>GROWTH STORY / DEMO</span><span>${p.no}</span></div><div class="mini-stamp">${stamp(p.id,true)}</div><h3>枝条的下一页</h3><p>${r[2]}</p><div class="back-sign">${r[0]} · 演示公开记录</div></div></div></div>`).join('')}</div><div class="growth-controls"><button class="solid-action" data-claim="${p.id}">接收这一枝 <span>↗</span></button><button class="line-action" data-care="${p.id}">养护来信 <span>→</span></button></div><p class="empty-note" style="padding:0 22px">公开记录是示意内容，插画用作照片占位；真实枝友内容尚未接入。</p></main>`}
const sampleLetters=[{id:'s1',plantId:'rose',category:'叶片',title:'月季新叶卷起来了，正常吗？',date:'2026.09.12',text:'枝条刚插下两周，最近新叶边缘有点卷。我把它放在南向阳台，每天有半天日照，要不要移到阴凉处？',replies:[{by:'枝友分享 · 演示',text:'我的月季也有过相似情况。先检查叶背有没有小虫，也留意盆土是不是太湿。',kind:'friend'},{by:'园艺建议 · 演示',text:'新扦插枝条容易失水。先避开正午直晒，保持通风与介质微湿；若出现虫害再对症处理。',kind:'gardener'}]},
{id:'s2',plantId:'crape',category:'扦插',title:'紫薇长了芽，是不是已经生根？',date:'2026.09.05',text:'扦插十多天后顶端长出新芽。很想知道现在可不可以换盆，担心碰坏它。',replies:[{by:'园艺建议 · 演示',text:'新芽可能消耗的是枝条原有养分，暂时不能据此判断生根。保持原状，观察后续稳定生长，再考虑换盆。',kind:'gardener'}]},
{id:'s3',plantId:'hydrangea',category:'光照',title:'绣球午后有点耷拉，怎么办？',date:'2026.08.27',text:'窗边下午会被太阳晒到，叶片看起来没有精神。是不是水浇得不够？',replies:[]}];
const allLetters=()=>[...data.letters,...sampleLetters.map(l=>({...l,replies:[...l.replies,...(data.sampleReplies?.[l.id]||[])]}))];
function letters(filter){const items=allLetters().filter(x=>!filter||x.plantId===filter);return `<main class="page letters-page"><div class="page-head"><div><span class="eyebrow">LETTERS BETWEEN GROWERS</span><h1 class="page-title"><span class="cn">枝友来信</span>LETTERS</h1><p class="page-intro">不确定该怎样照顾一根枝条？写下来，让经验慢慢抵达。</p></div><div class="page-counter">✉<br>NB</div></div><p class="letters-intro">信件与回复为本地演示数据；“园艺建议 · 演示”并非真实园艺人员在线答复。</p>${filter?`<div style="padding:0 22px 20px"><button class="text-back" data-nav="letters">← 查看所有来信</button><span class="eyebrow" style="float:right">${P[filter]?.name||''} / 养护来信</span></div>`:''}<div class="letters-board">${items.length?items.map((l,i)=>`<button class="envelope" data-letter="${l.id}" style="--tilt:${i%2?2:-2}deg" aria-label="打开${esc(l.title)}"><div class="envelope-top"><span>TO / ${P[l.plantId]?.name||'枝友'}<br>${P[l.plantId]?.no||''}</span><span class="letter-postage">NB<br>✳ 08</span></div><h3>${esc(l.title)}</h3><div class="envelope-bottom"><span>${esc(l.date)} · ${esc(l.category)}</span><span class="status-seal">${l.replies?.length?'已有解答':'等待回信'}</span></div></button>`).join(''):`<p class="empty-note">这枚邮票还没有来信。你可以寄出第一封。</p>`}</div><button class="letters-compose solid-action" data-nav="write-letter">写一封求助信 <span>↗</span></button></main>`}
function writeLetter(){return `<main class="page claim-page"><div class="claim-head"><button class="text-back" data-nav="letters">← 返回枝友来信</button><h1>把问题折进<br>一封信里。</h1><p>写给愿意分享经验的枝友 · 本地演示</p></div><section class="form-paper compose-paper" style="margin-top:0"><div class="form-top"><div><strong>DEAR GROWERS,</strong><span>求助信 / NB COMMUNITY</span></div><div class="postage">NB<br>✳ 08</div></div><label for="letter-plant">写给哪一枝？</label><select id="letter-plant">${plants.map(p=>`<option value="${p.id}" ${letterForm.plantId===p.id?'selected':''}>${p.name} · ${p.no}</option>`).join('')}</select><label for="letter-category">问题类型</label><select id="letter-category">${['扦插','光照','浇水','叶片','其他'].map(v=>`<option ${letterForm.category===v?'selected':''}>${v}</option>`).join('')}</select><label for="letter-title">信件标题</label><input id="letter-title" type="text" maxlength="45" placeholder="一句话说说发生了什么" value="${esc(letterForm.title)}"><label>植物近照（可选）</label><div class="upload-box" id="letter-photo-box"><span>＋ 轻点附上一张照片</span><input id="letter-photo" type="file" accept="image/*" aria-label="附上植物照片"></div><label for="letter-text">想问的问题</label><textarea id="letter-text" maxlength="600" placeholder="比如：它已经长芽了，可我不确定有没有生根……">${esc(letterForm.text)}</textarea><button class="solid-action" id="send-letter">封好并寄出 <span>✳</span></button><p id="letter-error" class="required-hint" hidden>请写下标题和问题内容。</p></section></main>`}
function focus(id,source){const p=P[id];if(!p)return;originView=hashParts()[0];focusId=id;const start=source?.getBoundingClientRect();const overlay=document.createElement('div');overlay.innerHTML=`<div class="focus-backdrop" data-close-focus></div><div class="focus-wrap"><div class="focus-top"><span>BOTANICAL STAMP / ${p.no}</span><button class="round-control" data-close-focus aria-label="关闭邮票放大">×</button></div><div class="focus-stamp" id="focus-stamp">${stamp(id)}<div class="magnifier" id="magnifier"></div></div><div class="focus-bottom"><div class="focus-bottom-row"><div><h2>${p.name}</h2><p>${p.latin.toUpperCase()} · ${p.no}</p></div><span class="lens-hint">移动 / 触摸放大镜 ⌕</span></div><div class="focus-actions"><button class="solid-action" data-detail="${id}">了解这一枝 <span>↗</span></button><button class="line-action" data-save-focus="${id}" aria-label="收藏这枚邮票">${data.saved.includes(id)?'★':'☆'}</button></div></div></div>`;document.body.append(overlay);overlay.id='focus-overlay';overlay.style.setProperty('--focus-bg',p.bg);overlay.style.setProperty('--focus-ink',p.ink);document.body.style.overflow='hidden';const end=overlay.querySelector('#focus-stamp');if(start){const er=end.getBoundingClientRect();const dx=start.left+start.width/2-(er.left+er.width/2),dy=start.top+start.height/2-(er.top+er.height/2),scale=start.width/er.width;end.animate([{transform:`translate(${dx}px,${dy}px) scale(${scale}) rotate(-7deg)`,opacity:.6},{transform:'translate(0,0) scale(1) rotate(0)',opacity:1}],{duration:650,easing:'cubic-bezier(.18,.75,.22,1)'})}overlay.querySelectorAll('[data-close-focus]').forEach(b=>b.onclick=closeFocus);overlay.querySelector('[data-detail]').onclick=()=>go('detail',id);overlay.querySelector('[data-save-focus]').onclick=()=>{toggleSave(id);overlay.querySelector('[data-save-focus]').textContent=data.saved.includes(id)?'★':'☆'};const lens=overlay.querySelector('#magnifier');const move=e=>{const r=end.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(x<0||y<0||x>r.width||y>r.height){lens.style.display='none';return}lens.style.display='block';lens.style.left=`${x}px`;lens.style.top=`${y}px`;lens.style.backgroundImage=`url('./assets/${p.art}')`;lens.style.backgroundSize=`${r.width*2.5}px ${r.height*2.5}px`;lens.style.backgroundPosition=`${(x/r.width)*100}% ${(y/r.height)*100}%`;lens.style.backgroundColor=p.bg};end.addEventListener('pointermove',move);end.addEventListener('pointerleave',()=>lens.style.display='none');end.addEventListener('pointerdown',move)}
function closeFocus(){document.querySelector('#focus-overlay')?.remove();document.body.style.overflow='';focusId=null}
function toggleSave(id){data.saved=data.saved.includes(id)?data.saved.filter(x=>x!==id):[...data.saved,id];persist();if(hashParts()[0]==='detail')render()}
async function readFile(input){const file=input.files?.[0];if(!file)return '';const blobUrl=URL.createObjectURL(file);try{const img=new Image();img.src=blobUrl;await img.decode();const ratio=Math.min(1,1000/Math.max(img.width,img.height));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*ratio);canvas.height=Math.round(img.height*ratio);const ctx=canvas.getContext('2d');ctx.fillStyle='#f8f5ea';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.8)}catch{return new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)})}finally{URL.revokeObjectURL(blobUrl)}}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));document.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>focus(b.dataset.focus,b));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const from=hashParts()[0];if(['home','claim-list','album'].includes(from))originView=from;go('detail',b.dataset.detail)});document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{claimForm={nick:'',place:'',light:'',form:''};go('claim',b.dataset.claim)});document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>toggleSave(b.dataset.save));document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>go('story',b.dataset.story));document.querySelectorAll('[data-care]').forEach(b=>b.onclick=()=>go('letters',b.dataset.care));document.querySelectorAll('[data-growth]').forEach(b=>b.onclick=()=>go('growth',b.dataset.growth));document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{claimForm.nick=document.querySelector('#claim-nick')?.value||'';claimForm[b.dataset.option]=b.dataset.value;const y=window.scrollY;render();window.scrollTo(0,y)});document.querySelector('#claim-nick')?.addEventListener('input',e=>claimForm.nick=e.target.value);document.querySelector('#submit-claim')?.addEventListener('click',()=>{claimForm.nick=document.querySelector('#claim-nick')?.value.trim()||'';if(!claimForm.nick||!claimForm.place||!claimForm.light||!claimForm.form){document.querySelector('#claim-error').hidden=false;return}const id=hashParts()[1],c={id:`NB-${Date.now().toString(36).toUpperCase()}`,plantId:id,...claimForm,status:'reserved',date:new Date().toLocaleDateString('zh-CN').replaceAll('/','.'),demo:true};data.claims.push(c);persist();render();window.scrollTo(0,0)});document.querySelectorAll('[data-pickup]').forEach(b=>b.onclick=()=>{const c=data.claims.find(x=>x.id===b.dataset.pickup);if(c){c.status='claimed';persist();render();window.scrollTo(0,0)}});document.querySelector('#show-record-form')?.addEventListener('click',()=>{const f=document.querySelector('#record-form');f.hidden=false;f.scrollIntoView({behavior:'smooth',block:'start'})});document.querySelector('#record-photo')?.addEventListener('change',async e=>{recordForm.photo=await readFile(e.target);const box=document.querySelector('#photo-box');box.querySelector('span').textContent=e.target.files[0]?.name||'已选择照片';if(recordForm.photo)box.insertAdjacentHTML('afterbegin',`<img class="upload-preview" src="${recordForm.photo}" alt="上传照片预览">`)});document.querySelector('#submit-record')?.addEventListener('click',()=>{recordForm.status=document.querySelector('#record-status').value;recordForm.text=document.querySelector('#record-text').value.trim();if(!recordForm.photo||!recordForm.text){document.querySelector('#record-error').hidden=false;return}data.postcards.push({id:`PC-${Date.now()}`,plantId:hashParts()[1],date:new Date().toLocaleDateString('zh-CN').replaceAll('/','.'),...recordForm,demo:false});persist();recordForm={status:'抽出新芽',text:'',photo:''};render();window.scrollTo(0,0)});document.querySelectorAll('.postcard').forEach(card=>{card.onclick=()=>card.classList.toggle('flipped');card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();card.classList.toggle('flipped')}}});document.querySelectorAll('[data-letter]').forEach(b=>b.onclick=()=>{b.classList.add('open');setTimeout(()=>openLetter(b.dataset.letter),220)});document.querySelector('#unread-letter')?.addEventListener('click',()=>{data.unread=false;persist();go('letters','crape');setTimeout(()=>openLetter('s2'),120)});document.querySelector('#letter-photo')?.addEventListener('change',async e=>{letterForm.photo=await readFile(e.target);document.querySelector('#letter-photo-box span').textContent=e.target.files[0]?.name||'已附照片'});document.querySelector('#send-letter')?.addEventListener('click',()=>{letterForm.plantId=document.querySelector('#letter-plant').value;letterForm.category=document.querySelector('#letter-category').value;letterForm.title=document.querySelector('#letter-title').value.trim();letterForm.text=document.querySelector('#letter-text').value.trim();if(!letterForm.title||!letterForm.text){document.querySelector('#letter-error').hidden=false;return}data.letters.unshift({id:`L-${Date.now()}`,date:new Date().toLocaleDateString('zh-CN').replaceAll('/','.'),...letterForm,replies:[]});persist();letterForm={plantId:'rose',category:'扦插',title:'',text:'',photo:''};const screen=document.createElement('div');screen.className='sent-envelope';screen.innerHTML='<div><div class="mail-graphic"><b>已寄出</b></div>这封信已经放进邮筒。<br><small style="font:600 11px var(--sans)">本地演示提交 · 等待回信</small></div>';document.body.append(screen);setTimeout(()=>{screen.remove();go('letters')},1300)})}
function openLetter(id){const l=allLetters().find(x=>x.id===id);if(!l)return;openLetterId=id;const el=document.createElement('div');el.className='letter-overlay';el.id='letter-overlay';el.innerHTML=`<article class="letter-sheet"><button class="round-control letter-close" aria-label="关闭信件">×</button><div class="eyebrow">NONGKE BRANCH POST / LETTER</div><h2>${esc(l.title)}</h2><div class="letter-meta">${P[l.plantId]?.name||''} · ${esc(l.category)} · ${esc(l.date)} · ${l.id.startsWith('s')?'演示信件':'本地来信'}</div>${l.photo?`<img class="letter-photo" src="${l.photo}" alt="求助信附图">`:''}<div class="letter-body">${esc(l.text)}</div><div class="eyebrow" style="margin-top:20px">REPLIES / ${(l.replies||[]).length}</div>${(l.replies||[]).map(r=>`<div class="reply ${r.kind==='gardener'?'gardener':''}"><span class="by">${esc(r.by)}</span><p>${esc(r.text)}</p></div>`).join('')||'<p class="empty-note">这封信还在等待回信。</p>'}<div class="reply-form"><input type="text" maxlength="300" placeholder="分享一条你的经验…" aria-label="回复内容"><button type="button">寄出回复</button></div></article>`;document.body.append(el);el.querySelector('.letter-close').onclick=()=>el.remove();el.onclick=e=>{if(e.target===el)el.remove()};el.querySelector('.reply-form button').onclick=()=>{const input=el.querySelector('.reply-form input');const text=input.value.trim();if(!text)return;if(l.id.startsWith('s')){data.sampleReplies??={};(data.sampleReplies[l.id]??=[]).push({by:'枝友分享 · 本地演示',text,kind:'friend'})}else{const original=data.letters.find(x=>x.id===l.id);original?.replies.push({by:'枝友分享 · 本地演示',text,kind:'friend'})}persist();el.remove();openLetter(l.id)}}
let scrollFrame=0;window.addEventListener('scroll',()=>{if(scrollFrame)return;scrollFrame=requestAnimationFrame(()=>{scrollFrame=0;if(hashParts()[0]!=='home')return;document.querySelectorAll('.field-stamp').forEach((el,i)=>{const amount=Math.min(24,window.scrollY*.035)*Math.sin(i*1.9+.6);el.style.setProperty('--drift',`${amount.toFixed(1)}px`)})})},{passive:true});
window.addEventListener('hashchange',()=>{closeFocus();render();window.scrollTo(0,0)});window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeFocus();document.querySelector('#letter-overlay')?.remove()}});render();
